package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.policy.OperationalPolicyVersion;import com.intermarche.backoffice.domain.shipping.ParcelControlPolicy;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(OperationalPolicyWorkflowTest.class)
class OperationalPolicyWorkflowTest extends ParcelWorkflowTest {
 Map<String,Object> current(String kind){return given().auth().oauth2(f.manager()).get("/operational-policies/current?storeId="+f.store()+"&type="+kind).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> sample(String kind){var defs=given().auth().oauth2(f.manager()).get("/operational-policies/catalog?storeId="+f.store()).then().statusCode(200).extract().jsonPath().<Map<String,Object>>getList("definitions");return new LinkedHashMap<>((Map<String,Object>)defs.stream().filter(d->kind.equals(d.get("type"))).findFirst().orElseThrow().get("testCase"));}
 Map<String,Object> post(String path,Map<String,Object> body,int status){return given().auth().oauth2(f.manager()).contentType("application/json").body(body).post("/operational-policies/"+path).then().statusCode(status).extract().jsonPath().getMap("$");}
 Map<String,Object> request(Map<String,Object> current,Map<String,Object> spec,Map<String,Object> test){return new LinkedHashMap<>(Map.of("storeId",f.store(),"specification",spec,"testCase",test,"expectedRevision",current.get("revision"),"requestKey",key(),"reason","Politique vérifiée dans un scénario de test"));}
 @Test void simulationDoesNotActivateAndVersionsStayImmutableWithIdempotentActivation(){var current=current("ParcelConstraints");var spec=new LinkedHashMap<>((Map<String,Object>)current.get("values"));spec.put("requireScan",true);var test=sample("ParcelConstraints");test.put("scanMatches",false);var input=request(current,spec,test);var simulation=post("simulate",input,200);assertEquals(false,((Map<?,?>)simulation.get("result")).get("allowed"));QuarkusTransaction.requiringNew().run(()->assertEquals(0,ParcelControlPolicy.count("store.id",f.store())));post("activate",input,409);input.put("simulationToken",simulation.get("simulationToken"));var activated=post("activate",input,200);post("activate",input,200);assertEquals(1,((List<?>)activated.get("history")).size());QuarkusTransaction.requiringNew().run(()->{assertTrue(ParcelControlPolicy.<ParcelControlPolicy>find("store.id",f.store()).firstResult().requireScan);assertEquals(1,OperationalPolicyVersion.count("store.id",f.store()));});var stale=new LinkedHashMap<>(input);stale.put("requestKey",key());post("activate",stale,409);var second=new LinkedHashMap<>((Map<String,Object>)activated.get("values"));second.put("requireScan",false);var next=request(activated,second,sample("ParcelConstraints"));next.put("simulationToken",post("simulate",next,200).get("simulationToken"));var updated=post("activate",next,200);var history=(List<Map<String,Object>>)updated.get("history");assertEquals(2,history.size());assertEquals(false,history.get(1).get("active"));assertEquals(true,((Map<?,?>)history.get(1).get("specification")).get("requireScan"));}
 @Test void mandatoryIndependenceCannotBeDisabledAndPickerCannotActivatePolicies(){var current=current("ApprovalConstraints");var spec=new LinkedHashMap<>((Map<String,Object>)current.get("values"));spec.put("independentApproverRequired",false);post("simulate",request(current,spec,sample("ApprovalConstraints")),400);given().auth().oauth2(f.picker()).contentType("application/json").body(request(current,spec,sample("ApprovalConstraints"))).post("/operational-policies/activate").then().statusCode(403);given().auth().oauth2(f.manager()).get("/operational-policies/current?storeId="+f.other()+"&type=ApprovalConstraints").then().statusCode(403);}
 @Test void legacyParcelPolicyEditsAreAlsoVersioned(){var policy=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"requestKey",key(),"expectedRevision",0,"requireWeight",true,"requireDimensions",false,"requireContentConfirmation",true,"requireScan",false));parcel(f.manager(),"/policy",policy).then().statusCode(200);parcel(f.manager(),"/policy",policy).then().statusCode(200);assertEquals(1,((List<?>)current("ParcelConstraints").get("history")).size());}
 @Test void activatedSupportLimitsAreEnforcedByTheRealPickingCommand(){line();var stock=stock();QuarkusTransaction.requiringNew().run(()->com.intermarche.backoffice.domain.order.Product.<com.intermarche.backoffice.domain.order.Product>findById(f.product()).referenceVolume=java.math.BigDecimal.TEN);attach(f.tote());var current=current("SupportConstraints");var spec=new LinkedHashMap<>((Map<String,Object>)current.get("values"));spec.put("maximumFillPercent",10);var input=request(current,spec,sample("SupportConstraints"));input.put("simulationToken",post("simulate",input,200).get("simulationToken"));post("activate",input,200);var pick=command("PICK");pick.putAll(Map.of("itemId",f.item(),"quantity",2,"toteCode",f.tote()));command(pick).then().statusCode(400);QuarkusTransaction.requiringNew().run(()->{assertEquals(com.intermarche.backoffice.domain.executing.PickedItem.PickStatus.PENDING,com.intermarche.backoffice.domain.executing.PickedItem.<com.intermarche.backoffice.domain.executing.PickedItem>findById(f.item()).status);eq(20,stocks.availability(stock.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);});}
 @Test void simulationRejectsNegativePhysicalValuesInsteadOfApprovingAFictitiousCapacity(){var c=current("SupportConstraints");var spec=(Map<String,Object>)c.get("values");var sample=sample("SupportConstraints");sample.put("capacityLiters",-10);post("simulate",request(c,spec,sample),400);var approval=current("ApprovalConstraints");var test=sample("ApprovalConstraints");test.put("elapsedMinutes",-1);post("simulate",request(approval,(Map<String,Object>)approval.get("values"),test),400);}

}
